export function medalFor(tier,seconds){
  if(typeof tier!=='string'||!Object.hasOwn(MEDALS,tier)||!Number.isFinite(seconds)||seconds<=0)return null;
  const table=MEDALS[tier];
  return ['gold','silver','bronze'].find(medal=>seconds<=table[medal])??null;
}
